new_cases = [
    {"id": "robert-pickton-victims", "name": "Robert Pickton Victims", "type": "Serial Killer Victims", "status": "Solved", "year": 2002, "date": "February 5, 2002", "state": "Canada", "city": "Port Coquitlam", "country": "Canada", "age": None, "gender": "Female", "summary": "Pig farmer Robert Pickton murdered women from Vancouver's Downtown Eastside. Convicted of six counts of second-degree murder, he was suspected of killing 49 women.", "lastSeen": "Various dates, Port Coquitlam, British Columbia, Canada", "tags": ["serial killer", "Canada", "2000s", "solved"], "sources": [{"title": "Robert Pickton - Wikipedia", "url": "https://en.wikipedia.org/wiki/Robert_Pickton"}, {"title": "Pickton trial - CBC", "url": "https://www.cbc.ca/news/canada/british-columbia/robert-pickton-pig-farmer-serial-killer-1.7126780"}, {"title": "Missing Women Commission of Inquiry", "url": "https://missingwomen.library.ubc.ca/"}], "narrative": ["Robert William Pickton was a pig farmer from Port Coquitlam, British Columbia, who lured vulnerable women—many of them sex workers and drug users—from Vancouver's Downtown Eastside to his farm where he murdered them. The victims' remains were disposed of on the farm property, some allegedly mixed with pork that was processed.", "The women began disappearing in the late 1990s, but their cases received little attention from police or media. Advocates and families of missing women argued that the victims' marginalized status led to inadequate investigation. A public inquiry later confirmed systemic failures in policing.", "In February 2002, police raided Pickton's farm on weapons charges and soon discovered DNA and remains of multiple missing women. The investigation became one of the largest in Canadian history, with forensic teams spending years processing the massive crime scene.", "Pickton was convicted of six counts of second-degree murder in 2007 and sentenced to life with no parole for 25 years. Charges related to 20 additional murders were stayed. Pickton claimed to have killed 49 women. He was killed in prison in 2024."], "timeline": [{"date": "2002-02-05", "event": "Police raid Pickton's farm; begin discovering remains."}, {"date": "2007-12-09", "event": "Pickton convicted of six counts of second-degree murder."}, {"date": "2024-05-31", "event": "Pickton killed in prison."}], "enriched": True},
    {"id": "evelyn-hartley-1953", "name": "Evelyn Hartley", "type": "Missing Person", "status": "Unsolved", "year": 1953, "date": "October 24, 1953", "state": "Wisconsin", "city": "La Crosse", "age": 15, "gender": "Female", "summary": "Fifteen-year-old babysitter Evelyn Hartley vanished from a home in La Crosse, Wisconsin. Bloodstains and her shoes were found at the scene. She was never found.", "lastSeen": "October 24, 1953, 2426 Hoeschler Drive, La Crosse, Wisconsin", "tags": ["missing person", "child", "Wisconsin", "1950s", "unsolved"], "sources": [{"title": "Disappearance of Evelyn Hartley - Wikipedia", "url": "https://en.wikipedia.org/wiki/Disappearance_of_Evelyn_Hartley"}, {"title": "Evelyn Hartley case - La Crosse Tribune", "url": "https://lacrossetribune.com/news/local/evelyn-hartley/"}, {"title": "Evelyn Hartley - Charley Project", "url": "https://charleyproject.org/case/evelyn-grace-hartley"}], "narrative": ["On the evening of October 24, 1953, fifteen-year-old Evelyn Hartley was babysitting at the home of Viggo Rasmussen at 2426 Hoeschler Drive in La Crosse, Wisconsin. When her father called to check on her and received no answer, he drove to the house and found a disturbing scene.", "The lights were on, the radio was playing, and the baby was safe in its crib, but Evelyn was gone. A basement window had been forced open, and bloodstains were found on the basement floor and outside the house. One of Evelyn's shoes was found in the yard, and her other shoe and eyeglasses were found nearby.", "Bloodstained clothing belonging to Evelyn was later found along Highway 14 south of La Crosse. Despite one of the largest searches in Wisconsin history, involving thousands of volunteers and police from multiple agencies, Evelyn was never found.", "The case remains La Crosse's most famous unsolved mystery. Over the decades, several suspects have been investigated, including serial killer Ed Gein, but no definitive link has been established."], "timeline": [{"date": "1953-10-24", "event": "Evelyn Hartley vanishes while babysitting in La Crosse."}, {"date": "1953-10-25", "event": "Bloodstained clothing found along Highway 14."}], "enriched": True},
    {"id": "lisa-irwin-2011-b", "name": "Brittany Mae Smith", "type": "Homicide", "status": "Solved", "year": 2011, "date": "November 4, 2011", "state": "Virginia", "city": "Salem", "age": 12, "gender": "Female", "summary": "Twelve-year-old Brittany Mae Smith was murdered by Jeffrey Easley, who was having a relationship with her mother. Her mother was also convicted of second-degree murder for failing to protect her.", "lastSeen": "November 4, 2011, Salem, Virginia", "tags": ["homicide", "child", "Virginia", "2010s", "solved"], "sources": [{"title": "Brittany Mae Smith case - Roanoke Times", "url": "https://roanoke.com/news/crime/brittany-mae-smith-case/"}, {"title": "Brittany Mae Smith murder - WDBJ7", "url": "https://www.wdbj7.com/content/news/brittany-mae-smith-murder/"}, {"title": "Tina Smith conviction - AP News", "url": "https://apnews.com/article/tina-smith-brittany-smith-murder"}], "narrative": ["On November 4, 2011, twelve-year-old Brittany Mae Smith was reported missing from her home in Salem, Virginia. Her mother, Tina Smith, initially told police that Brittany had been taken by an unknown man. However, the investigation quickly revealed inconsistencies in her story.", "Evidence led police to Jeffrey Easley, Tina Smith's boyfriend, who had been living with the family. Brittany's body was found in a closet at the residence. She had been strangled and sexually assaulted.", "Easley was arrested and charged with first-degree murder, rape, and abduction. He was convicted and sentenced to two life sentences plus 20 years. The investigation revealed that Tina Smith had been aware of Easley's abuse of Brittany but had failed to protect her daughter.", "Tina Smith was also charged and convicted of second-degree murder for her role in failing to protect Brittany. She was sentenced to 33 years in prison."], "timeline": [{"date": "2011-11-04", "event": "Brittany Mae Smith reported missing."}, {"date": "2011-11-05", "event": "Body found; Jeffrey Easley arrested."}, {"date": "2012-01-01", "event": "Easley convicted; sentenced to two life terms plus 20 years."}], "enriched": True},
    {"id": "dorothy-jane-scott-1980", "name": "Dorothy Jane Scott", "type": "Missing Person", "status": "Unsolved", "year": 1980, "date": "May 28, 1980", "state": "California", "city": "Anaheim", "age": 32, "gender": "Female", "summary": "Dorothy Jane Scott disappeared from a hospital parking lot in Anaheim, California. An unknown stalker had been harassing her for months before her disappearance and continued calling her mother afterward.", "lastSeen": "May 28, 1980, UCI Medical Center parking lot, Anaheim, California", "tags": ["missing person", "California", "1980s", "stalking", "unsolved"], "sources": [{"title": "Disappearance of Dorothy Jane Scott - Wikipedia", "url": "https://en.wikipedia.org/wiki/Disappearance_of_Dorothy_Jane_Scott"}, {"title": "Dorothy Scott case - Orange County Register", "url": "https://www.ocregister.com/dorothy-jane-scott-cold-case/"}, {"title": "Dorothy Scott - Charley Project", "url": "https://charleyproject.org/case/dorothy-jane-scott"}], "narrative": ["On the evening of May 28, 1980, thirty-two-year-old Dorothy Jane Scott drove a coworker to the UCI Medical Center in Anaheim after he was bitten by a black widow spider. While waiting in the parking lot for the coworker to be treated, she went to bring her car around. Witnesses saw her car speeding out of the parking lot with its headlights off. Dorothy was never seen alive again.", "In the months before her disappearance, Dorothy had been receiving threatening phone calls from an unknown man who appeared to know her daily movements, clothing choices, and whereabouts. Despite reporting the harassment, police were unable to identify the caller.", "After Dorothy vanished, the calls continued—now directed at her mother, Vera Scott. The caller alternated between declaring his love for Dorothy and claiming he had killed her. The calls continued for years.", "In August 1984, Dorothy's skeletal remains were found in a shallow grave near a rural road in Riverside County. The cause of death could not be determined. Despite DNA evidence collected at the scene, the case remains unsolved."], "timeline": [{"date": "1980-05-28", "event": "Dorothy Scott vanishes from a hospital parking lot in Anaheim."}, {"date": "1980-06-01", "event": "Stalker begins calling Dorothy's mother."}, {"date": "1984-08-06", "event": "Dorothy's remains found in Riverside County."}], "enriched": True},
    {"id": "matthew-chase-2013", "name": "Amy Lord", "type": "Homicide", "status": "Solved", "year": 2013, "date": "July 23, 2013", "state": "Massachusetts", "city": "Boston", "age": 24, "gender": "Female", "summary": "Twenty-four-year-old Amy Lord was kidnapped from her South Boston apartment, forced to withdraw money from ATMs, then murdered. Edwin Alemany was convicted and sentenced to life.", "lastSeen": "July 23, 2013, South Boston, Massachusetts", "tags": ["homicide", "Massachusetts", "2010s", "kidnapping", "solved"], "sources": [{"title": "Murder of Amy Lord - Wikipedia", "url": "https://en.wikipedia.org/wiki/Murder_of_Amy_Lord"}, {"title": "Edwin Alemany conviction - Boston Globe", "url": "https://www.bostonglobe.com/metro/2015/10/amy-lord-murder-trial/"}, {"title": "Amy Lord case - NBC Boston", "url": "https://www.nbcboston.com/news/local/amy-lord-murder-trial/"}], "narrative": ["On July 23, 2013, Amy Lord, a 24-year-old graduate of the College of the Holy Cross, was kidnapped from her apartment in South Boston, Massachusetts. Surveillance footage later showed her being forced at knifepoint to withdraw cash from multiple ATMs across the Boston area.", "Amy's body was found later that day in Hyde Park's Stony Brook Reservation. She had been stabbed multiple times. The brutal nature of the crime and the daylight kidnapping shocked the city.", "Edwin Alemany, a 28-year-old with a long criminal history, was identified through ATM surveillance footage and DNA evidence. He had been released from custody just weeks before the murder despite a string of violent offenses.", "Alemany was convicted of first-degree murder in 2015 and sentenced to life in prison without parole. The case prompted calls for reform to the criminal justice system's handling of repeat violent offenders."], "timeline": [{"date": "2013-07-23", "event": "Amy Lord kidnapped and murdered in Boston."}, {"date": "2013-07-24", "event": "Edwin Alemany arrested."}, {"date": "2015-10-29", "event": "Alemany convicted; sentenced to life without parole."}], "enriched": True},
    {"id": "vanessa-guillen-2020", "name": "Vanessa Guillen", "type": "Homicide", "status": "Solved", "year": 2020, "date": "April 22, 2020", "state": "Texas", "city": "Killeen", "age": 20, "gender": "Female", "summary": "Army specialist Vanessa Guillen was bludgeoned to death by fellow soldier Aaron Robinson at Fort Hood. The case exposed systemic failures in military sexual harassment reporting.", "lastSeen": "April 22, 2020, Fort Hood, Texas", "tags": ["homicide", "Texas", "2020s", "military", "sexual harassment", "solved"], "sources": [{"title": "Murder of Vanessa Guillen - Wikipedia", "url": "https://en.wikipedia.org/wiki/Murder_of_Vanessa_Guillen"}, {"title": "Vanessa Guillen case - CNN", "url": "https://www.cnn.com/2020/07/02/us/vanessa-guillen-fort-hood/index.html"}, {"title": "I Am Vanessa Guillen Act", "url": "https://www.congress.gov/bill/117th-congress/house-bill/8913"}], "narrative": ["On April 22, 2020, twenty-year-old Army Specialist Vanessa Guillen disappeared from Fort Hood in Killeen, Texas, one of the largest military installations in the United States. Her family reported that she had told them she was being sexually harassed by a superior but was afraid to report it through official channels.", "After a two-month search, Guillen's dismembered remains were found on June 30 near the Leon River, about 20 miles from Fort Hood. Evidence pointed to Specialist Aaron David Robinson, who had bludgeoned Guillen with a hammer in an armory room and then enlisted his girlfriend Cecily Aguilar to help dismember and dispose of the body.", "When investigators attempted to arrest Robinson on July 1, he fled the post and fatally shot himself. Aguilar was arrested and eventually pleaded guilty to accessory after the fact and three counts of tampering with evidence. She was sentenced to 30 years in prison.", "The case sparked a national reckoning about sexual harassment and assault in the U.S. military. The 'I Am Vanessa Guillen Act,' signed into law in 2021, reformed how the military handles sexual harassment complaints by removing the chain of command from the reporting process."], "timeline": [{"date": "2020-04-22", "event": "Vanessa Guillen disappears from Fort Hood."}, {"date": "2020-06-30", "event": "Guillen's remains found near the Leon River."}, {"date": "2020-07-01", "event": "Aaron Robinson dies by suicide as investigators close in."}, {"date": "2021-12-27", "event": "'I Am Vanessa Guillen Act' signed into law."}], "enriched": True},
    {"id": "ann-marie-burr-1961", "name": "Ann Marie Burr", "type": "Missing Person", "status": "Unsolved", "year": 1961, "date": "August 31, 1961", "state": "Washington", "city": "Tacoma", "age": 8, "gender": "Female", "summary": "Eight-year-old Ann Marie Burr vanished from her Tacoma, Washington home. Serial killer Ted Bundy, who lived nearby as a teenager, has been speculated as a suspect but the connection was never proven.", "lastSeen": "August 31, 1961, her family home in Tacoma, Washington", "tags": ["missing person", "child", "Washington", "1960s", "Ted Bundy suspect", "unsolved"], "sources": [{"title": "Disappearance of Ann Marie Burr - Wikipedia", "url": "https://en.wikipedia.org/wiki/Disappearance_of_Ann_Marie_Burr"}, {"title": "Ann Marie Burr case - Tacoma News Tribune", "url": "https://www.thenewstribune.com/news/local/crime/ann-marie-burr/"}, {"title": "Ann Marie Burr - Charley Project", "url": "https://charleyproject.org/case/ann-marie-burr"}], "narrative": ["On August 31, 1961, eight-year-old Ann Marie Burr vanished from her family's home on North 14th Street in Tacoma, Washington. Her parents discovered she was missing in the early morning hours after finding her bedroom window open and a side door unlocked. Despite an intensive search, she was never found.", "The case attracted renewed attention years later when serial killer Ted Bundy, who had grown up in the same Tacoma neighborhood and would have been 14 years old at the time, was suggested as a possible suspect. Bundy denied involvement in the Burr disappearance before his execution in 1989, though he acknowledged he had been a troubled teenager.", "DNA testing conducted in the 2000s was inconclusive. While the Ted Bundy theory remains popular in true crime circles, investigators have never been able to establish a definitive connection.", "Ann Marie Burr's disappearance remains Tacoma's oldest unsolved missing child case. The Tacoma Police Department continues to maintain the case file."], "timeline": [{"date": "1961-08-31", "event": "Ann Marie Burr vanishes from her Tacoma home."}, {"date": "1989-01-24", "event": "Ted Bundy denies involvement before his execution."}], "enriched": True},
    {"id": "lyle-stevik-2001", "name": "Lyle Stevik", "type": "Suspicious Death", "status": "Solved", "year": 2001, "date": "September 17, 2001", "state": "Washington", "city": "Amanda Park", "age": 25, "gender": "Male", "summary": "A man registered at a motel under the name 'Lyle Stevik' was found dead by suicide. His true identity remained unknown for 17 years until DNA genealogy identified him in 2018.", "lastSeen": "September 17, 2001, Lake Quinault Inn, Amanda Park, Washington", "tags": ["unidentified person", "Washington", "2000s", "DNA", "solved"], "sources": [{"title": "Lyle Stevik - Wikipedia", "url": "https://en.wikipedia.org/wiki/Lyle_Stevik"}, {"title": "Lyle Stevik identified - DNA Doe Project", "url": "https://dnadoeproject.org/case/lyle-stevik/"}, {"title": "Lyle Stevik case - Seattle Times", "url": "https://www.seattletimes.com/seattle-news/lyle-stevik-mystery-solved/"}], "narrative": ["On September 17, 2001, a young man checked into the Lake Quinault Inn in Amanda Park, a small community on Washington state's Olympic Peninsula, using the name 'Lyle Stevik,' an apparent reference to a character in the Joyce Carol Oates novel 'You Must Remember This.' He was found dead by suicide in his room the next day.", "The man carried no identification, and the name he registered under was false. An autopsy estimated he was in his mid-twenties. Investigators were unable to match him to any missing person reports, and despite years of investigation, his true identity remained unknown.", "The case became one of the internet's most discussed unidentified person cases, with online communities dedicating years to researching potential matches. The DNA Doe Project, a nonprofit using genetic genealogy to identify unidentified remains, took on the case.", "In 2018, genetic genealogy identified the man. At the family's request, his real name has not been publicly released. The resolution brought closure while respecting the privacy of his loved ones."], "timeline": [{"date": "2001-09-17", "event": "A man using the name 'Lyle Stevik' checks into the Lake Quinault Inn."}, {"date": "2001-09-18", "event": "The man found dead; his identity unknown."}, {"date": "2018-05-08", "event": "DNA genealogy identifies the man; family requests privacy."}], "enriched": True},
    {"id": "gannon-stauch-2020", "name": "Gannon Stauch", "type": "Homicide", "status": "Solved", "year": 2020, "date": "January 27, 2020", "state": "Colorado", "city": "Colorado Springs", "age": 11, "gender": "Male", "summary": "Eleven-year-old Gannon Stauch was murdered by his stepmother Letecia Stauch in Colorado Springs. She transported his body to Florida. She was found guilty but not guilty by reason of insanity.", "lastSeen": "January 27, 2020, his home in Colorado Springs, Colorado", "tags": ["homicide", "child", "Colorado", "2020s", "stepparent", "solved"], "sources": [{"title": "Murder of Gannon Stauch - Wikipedia", "url": "https://en.wikipedia.org/wiki/Murder_of_Gannon_Stauch"}, {"title": "Letecia Stauch trial - Denver Post", "url": "https://www.denverpost.com/tag/gannon-stauch/"}, {"title": "Gannon Stauch case - KKTV", "url": "https://www.kktv.com/content/news/gannon-stauch/"}], "narrative": ["On January 27, 2020, eleven-year-old Gannon Stauch was reported missing from his home in Lorson Ranch, a neighborhood in Colorado Springs, Colorado. His stepmother, Letecia Stauch, claimed Gannon had left the house to go to a friend's home but never returned.", "The investigation quickly focused on Letecia, whose account of events contained inconsistencies. Evidence including blood found in the family's SUV and house contradicted her story. Despite the growing suspicion, Letecia maintained her innocence and fled to South Carolina.", "On March 2, 2020, Gannon's remains were discovered under a bridge near Pace, Florida, having been transported there by Letecia. She was arrested in Myrtle Beach, South Carolina, and extradited to Colorado.", "Letecia Stauch's trial in 2023 was notable for her erratic courtroom behavior and her defense team's insanity claim. She was found guilty of first-degree murder but also found not guilty by reason of insanity, resulting in commitment to the Colorado Mental Health Institute rather than prison."], "timeline": [{"date": "2020-01-27", "event": "Gannon Stauch reported missing from Colorado Springs."}, {"date": "2020-03-02", "event": "Gannon's remains found in Florida."}, {"date": "2020-03-02", "event": "Letecia Stauch arrested in South Carolina."}, {"date": "2023-05-29", "event": "Letecia found guilty of murder; committed to mental health institute."}], "enriched": True},
    {"id": "pamela-butler-2009", "name": "Pamela Butler", "type": "Missing Person", "status": "Solved", "year": 2009, "date": "February 5, 2009", "state": "Washington, D.C.", "city": "Washington", "age": 47, "gender": "Female", "summary": "Government contractor Pamela Butler vanished from her D.C. home. Her neighbor Nathaniel Williams confessed years later to killing her during an argument.", "lastSeen": "February 5, 2009, her home on Gallatin Street NW, Washington, D.C.", "tags": ["missing person", "homicide", "Washington D.C.", "2000s", "solved"], "sources": [{"title": "Disappearance of Pamela Butler - Wikipedia", "url": "https://en.wikipedia.org/wiki/Disappearance_of_Pamela_Butler"}, {"title": "Pamela Butler case - Washington Post", "url": "https://www.washingtonpost.com/local/crime/pamela-butler-case/"}, {"title": "Nathaniel Williams confession - NBC Washington", "url": "https://www.nbcwashington.com/news/local/pamela-butler-case-neighbor-confession/"}], "narrative": ["On February 5, 2009, forty-seven-year-old Pamela Butler, a government contractor who worked for the Department of the Interior, was last seen at her home on Gallatin Street NW in Washington, D.C. When she failed to report to work, colleagues became concerned and contacted police.", "Police found Butler's home undisturbed, with her car, purse, and personal belongings still inside. Her three cats were found unattended. Despite a thorough investigation, no trace of Pamela was found for years.", "In 2020, Nathaniel Williams, a longtime neighbor and acquaintance, confessed to killing Pamela during an argument in 2009. He told investigators he had disposed of her body in a dumpster. Her remains were never recovered.", "Williams pleaded guilty to voluntary manslaughter and was sentenced to 14 years in prison. The case highlighted the challenges of solving missing person cases when the victim's body cannot be found."], "timeline": [{"date": "2009-02-05", "event": "Pamela Butler last seen at her home in Washington, D.C."}, {"date": "2009-02-09", "event": "Reported missing after failing to appear at work."}, {"date": "2020-01-01", "event": "Nathaniel Williams confesses to killing Butler."}], "enriched": True},
    {"id": "diane-schuler-2009", "name": "Diane Schuler", "type": "Multiple Homicide", "status": "Solved", "year": 2009, "date": "July 26, 2009", "state": "New York", "city": "West Nyack", "age": 36, "gender": "Female", "summary": "Diane Schuler drove the wrong way on the Taconic State Parkway while intoxicated, killing herself, her daughter, three nieces, and three men in another vehicle. Her family disputed the toxicology findings.", "lastSeen": "July 26, 2009, Taconic State Parkway, Westchester County, New York", "tags": ["multiple homicide", "New York", "2000s", "drunk driving", "solved"], "sources": [{"title": "Taconic State Parkway crash - Wikipedia", "url": "https://en.wikipedia.org/wiki/2009_Taconic_State_Parkway_crash"}, {"title": "Diane Schuler case - New York Times", "url": "https://www.nytimes.com/2009/08/05/nyregion/05crash.html"}, {"title": "There's Something Wrong with Aunt Diane - HBO", "url": "https://www.hbo.com/movies/theres-something-wrong-with-aunt-diane"}], "narrative": ["On July 26, 2009, Diane Schuler drove her minivan the wrong way for 1.7 miles on the Taconic State Parkway in Westchester County, New York, before colliding head-on with an SUV. The crash killed Schuler, her two-year-old daughter Erin, her three nieces (Emma, Alyson, and Kate Hance), and three men in the SUV (Michael Bastardi Sr., Guy Bastardi, and Daniel Longo). Schuler's five-year-old son Bryan survived.", "Toxicology reports revealed that Schuler had a blood alcohol level of 0.19 percent—more than twice the legal limit—and had recently smoked marijuana. A broken vodka bottle was found in the minivan. These findings stunned her family and community, who described Schuler as a responsible, loving mother.", "Her husband Daniel Schuler and his attorney publicly disputed the toxicology results, insisting Diane was not an alcoholic and suggesting a medical condition such as a dental abscess had caused disorientation. An autopsy found no medical explanation for her behavior.", "The case became the subject of the 2011 HBO documentary 'There's Something Wrong with Aunt Diane,' which explored the disconnect between the woman her family described and the toxicological evidence."], "timeline": [{"date": "2009-07-26", "event": "Diane Schuler drives wrong way on Taconic Parkway; eight killed."}, {"date": "2009-08-04", "event": "Toxicology reveals high blood alcohol and marijuana use."}, {"date": "2011-07-25", "event": "HBO documentary 'There's Something Wrong with Aunt Diane' premieres."}], "enriched": True},
    {"id": "mark-hacking-2004", "name": "Lori Hacking", "type": "Homicide", "status": "Solved", "year": 2004, "date": "July 19, 2004", "state": "Utah", "city": "Salt Lake City", "age": 27, "gender": "Female", "summary": "Lori Hacking was murdered by her husband Mark after she discovered he had lied about being accepted to medical school. He disposed of her body in a dumpster.", "lastSeen": "July 19, 2004, her apartment in Salt Lake City, Utah", "tags": ["homicide", "Utah", "2000s", "domestic violence", "solved"], "sources": [{"title": "Murder of Lori Hacking - Wikipedia", "url": "https://en.wikipedia.org/wiki/Murder_of_Lori_Hacking"}, {"title": "Mark Hacking case - Deseret News", "url": "https://www.deseret.com/utah/mark-hacking-lori-murder/"}, {"title": "Mark Hacking conviction - CNN", "url": "https://www.cnn.com/2005/LAW/06/06/hacking.trial/index.html"}], "narrative": ["On July 19, 2004, Mark Hacking reported his wife Lori, 27, missing in Salt Lake City, claiming she had failed to return from a morning jog in Memory Grove Park. A massive search was launched, but the investigation quickly turned to Mark when his elaborate web of lies unraveled.", "Investigators discovered Mark had not been accepted to medical school at the University of North Carolina as he claimed. In fact, he had never graduated from the University of Utah. He had been fabricating his academic career for years, and Lori had recently discovered the deception.", "The night before reporting Lori missing, Mark had shot her in the head while she slept and disposed of her body in a dumpster at his workplace. Her remains were found in a landfill in October 2004.", "Mark Hacking pleaded guilty to first-degree murder in 2005 and was sentenced to six years to life in prison."], "timeline": [{"date": "2004-07-19", "event": "Lori Hacking reported missing in Salt Lake City."}, {"date": "2004-07-24", "event": "Mark Hacking's lies about medical school exposed."}, {"date": "2004-10-01", "event": "Lori's remains found in a landfill."}, {"date": "2005-06-06", "event": "Mark pleads guilty; sentenced to six years to life."}], "enriched": True},
    {"id": "morgan-nick-1995", "name": "Morgan Nick", "type": "Abduction", "status": "Unsolved", "year": 1995, "date": "June 9, 1995", "state": "Arkansas", "city": "Alma", "age": 6, "gender": "Female", "summary": "Six-year-old Morgan Nick was abducted from a Little League baseball game in Alma, Arkansas. Despite a large-scale investigation, she has never been found.", "lastSeen": "June 9, 1995, Little League field, Alma, Arkansas", "tags": ["abduction", "child", "Arkansas", "1990s", "unsolved"], "sources": [{"title": "Disappearance of Morgan Nick - Wikipedia", "url": "https://en.wikipedia.org/wiki/Disappearance_of_Morgan_Nick"}, {"title": "Morgan Nick Foundation", "url": "https://www.morgannickfoundation.com/"}, {"title": "Morgan Nick case - FBI", "url": "https://www.fbi.gov/wanted/kidnap/morgan-nick"}], "narrative": ["On June 9, 1995, six-year-old Morgan Chauntel Nick attended a Little League baseball game in Alma, Arkansas, with her mother Colleen. After the game, Morgan was catching lightning bugs with other children in the parking lot area while her mother sat in the bleachers nearby. When Colleen went to collect Morgan, the girl was gone.", "A witness reported seeing a man near a red pickup truck talking to the children. Morgan was described as having been seen near the truck. A massive search was launched immediately, but no trace of Morgan was found.", "The investigation identified a suspect description—a white male in his late thirties to early forties with a mustache driving a red pickup truck—but despite thousands of tips and years of investigation by the FBI and Arkansas State Police, no arrest has been made.", "Morgan's mother Colleen established the Morgan Nick Foundation, which has become a leading organization in child safety education in Arkansas and nationally. The case remains one of the most high-profile missing child cases in the state."], "timeline": [{"date": "1995-06-09", "event": "Morgan Nick abducted from a Little League field in Alma, Arkansas."}, {"date": "1995-06-10", "event": "Massive search launched; witness describes suspect and red truck."}], "enriched": True},
    {"id": "niqui-mccown-2001", "name": "Niqui McCown", "type": "Missing Person", "status": "Unsolved", "year": 2001, "date": "July 15, 2001", "state": "Ohio", "city": "Dayton", "age": 34, "gender": "Female", "summary": "Niqui McCown disappeared after leaving work in Dayton, Ohio. Her car was found abandoned at a nearby apartment complex. She has never been found.", "lastSeen": "July 15, 2001, leaving work in Dayton, Ohio", "tags": ["missing person", "Ohio", "2000s", "unsolved"], "sources": [{"title": "Disappearance of Niqui McCown - Wikipedia", "url": "https://en.wikipedia.org/wiki/Disappearance_of_Niqui_McCown"}, {"title": "Niqui McCown case - Dayton Daily News", "url": "https://www.daytondailynews.com/news/crime/niqui-mccown-missing/"}, {"title": "Niqui McCown - Charley Project", "url": "https://charleyproject.org/case/niqui-mccown"}], "narrative": ["On July 15, 2001, thirty-four-year-old Niqui McCown left her job at a Dayton, Ohio medical facility and was never seen again. Her car was found abandoned at an apartment complex near her workplace the following day.", "The investigation focused on several persons of interest, including men Niqui had been dating. Despite the efforts of the Dayton Police Department and the FBI, no arrests have been made.", "Niqui's family has remained active in keeping her case in the public eye, and the case has been featured on multiple true crime programs.", "The case remains one of Dayton's most prominent unsolved disappearances."], "timeline": [{"date": "2001-07-15", "event": "Niqui McCown disappears after leaving work in Dayton."}, {"date": "2001-07-16", "event": "Her car found abandoned at a nearby apartment complex."}], "enriched": True},
    {"id": "danielle-van-dam-2002", "name": "Danielle van Dam", "type": "Abduction", "status": "Solved", "year": 2002, "date": "February 1, 2002", "state": "California", "city": "San Diego", "age": 7, "gender": "Female", "summary": "Seven-year-old Danielle van Dam was kidnapped from her bedroom by neighbor David Westerfield. Her remains were found weeks later. Westerfield was sentenced to death.", "lastSeen": "February 1, 2002, her bedroom in Sabre Springs, San Diego, California", "tags": ["abduction", "homicide", "child", "California", "2000s", "solved"], "sources": [{"title": "Murder of Danielle van Dam - Wikipedia", "url": "https://en.wikipedia.org/wiki/Murder_of_Danielle_van_Dam"}, {"title": "David Westerfield trial - San Diego Union-Tribune", "url": "https://www.sandiegouniontribune.com/news/courts/vandam/"}, {"title": "Danielle van Dam case - CNN", "url": "https://www.cnn.com/2002/LAW/08/21/ctv.vandam.verdict/index.html"}], "narrative": ["On February 2, 2002, seven-year-old Danielle Nicole van Dam was discovered missing from her bedroom in the Sabre Springs neighborhood of San Diego, California. Her parents had been out with friends the previous evening, and the family's sliding glass door had been left unlocked.", "Suspicion quickly fell on David Westerfield, a 50-year-old neighbor and engineer who lived two houses away. Westerfield had been seen at a bar where Danielle's parents socialized, and he left on an impromptu trip in his motorhome the morning after Danielle disappeared.", "Danielle's remains were found on February 27 in a rural area east of San Diego. DNA evidence linked Westerfield to the crime, including Danielle's blood and hair found in his motorhome and his laundry.", "Westerfield was convicted of kidnapping, murder, and possession of child pornography in August 2002. He was sentenced to death."], "timeline": [{"date": "2002-02-02", "event": "Danielle van Dam discovered missing from her bedroom."}, {"date": "2002-02-22", "event": "David Westerfield arrested."}, {"date": "2002-02-27", "event": "Danielle's remains found east of San Diego."}, {"date": "2002-08-21", "event": "Westerfield convicted; sentenced to death."}], "enriched": True},
    {"id": "karen-mitchell-1997", "name": "Karen Mitchell", "type": "Missing Person", "status": "Unsolved", "year": 1997, "date": "November 25, 1997", "state": "California", "city": "Eureka", "age": 16, "gender": "Female", "summary": "Sixteen-year-old Karen Mitchell vanished while walking to her aunt's house in Eureka, California. She has been linked to a possible serial killer operating on the Redwood Highway.", "lastSeen": "November 25, 1997, walking near Henderson Center, Eureka, California", "tags": ["missing person", "child", "California", "1990s", "unsolved"], "sources": [{"title": "Disappearance of Karen Mitchell - Wikipedia", "url": "https://en.wikipedia.org/wiki/Disappearance_of_Karen_Mitchell"}, {"title": "Karen Mitchell case - Times-Standard", "url": "https://www.times-standard.com/karen-mitchell-cold-case/"}, {"title": "Karen Mitchell - Charley Project", "url": "https://charleyproject.org/case/karen-marie-mitchell"}], "narrative": ["On November 25, 1997, sixteen-year-old Karen Mitchell was last seen walking near the Henderson Center shopping area in Eureka, California, reportedly on her way to visit her aunt. She was never seen again.", "Karen's disappearance occurred in a region that had seen several other women and girls go missing along the Redwood Highway corridor. Investigators explored possible connections to other cases, raising the possibility of a serial offender operating in Humboldt County.", "The Eureka Police Department and FBI investigated numerous leads and persons of interest over the years. Despite periodic renewed efforts, including DNA analysis, no charges have been filed.", "Karen's mother and family have kept her case in the public eye. The disappearance remains one of the most prominent unsolved cases in northern California."], "timeline": [{"date": "1997-11-25", "event": "Karen Mitchell vanishes while walking in Eureka, California."}, {"date": "1997-11-26", "event": "Reported missing; search launched."}], "enriched": True},
    {"id": "lisk-sisters-1997", "name": "Lisk Sisters", "type": "Abduction", "status": "Solved", "year": 1996, "date": "September 1, 1996", "state": "Virginia", "city": "Spotsylvania", "age": None, "gender": "Female", "summary": "Sisters Kati (15) and Kristin (12) Lisk were abducted from their Spotsylvania, Virginia home. Their bodies were found in a river. Richard Evonitz, linked through DNA, died by suicide during arrest.", "lastSeen": "September 1, 1996, Spotsylvania County, Virginia", "tags": ["abduction", "homicide", "children", "Virginia", "1990s", "serial killer", "solved"], "sources": [{"title": "Richard Evonitz - Wikipedia", "url": "https://en.wikipedia.org/wiki/Richard_Evonitz"}, {"title": "Lisk sisters case - Richmond Times-Dispatch", "url": "https://richmond.com/news/local/crime/evonitz-lisk-sisters/"}, {"title": "Evonitz murders - FBI", "url": "https://www.fbi.gov/news/stories/richard-evonitz-serial-killer"}], "narrative": ["On September 1, 1996, sisters Kati Lisk (15) and Kristin Lisk (12) disappeared from their home in Spotsylvania County, Virginia, after being dropped off by their school bus. Their bookbags were found on the front porch, suggesting they had entered the house before being taken.", "Five days later, their bodies were found in a river in Stafford County. The case was linked to the 1996 kidnapping and murder of another girl, 16-year-old Sofia Silva, who had disappeared from her front yard in the same county just five months earlier.", "The cases went unsolved for years until 2002, when DNA evidence connected both crimes to Richard Marc Evonitz, a former Spotsylvania resident who had moved to South Carolina. The breakthrough came when Evonitz abducted a 15-year-old girl in Columbia, South Carolina, who managed to escape and identify him.", "When police attempted to arrest Evonitz on June 27, 2002, he fled in his car and died by suicide during a high-speed chase. DNA confirmed his involvement in the murders of the Lisk sisters and Sofia Silva."], "timeline": [{"date": "1996-09-01", "event": "Kati and Kristin Lisk abducted from their home in Spotsylvania."}, {"date": "1996-09-06", "event": "Their bodies found in the South Anna River."}, {"date": "2002-06-27", "event": "Richard Evonitz dies by suicide; DNA links him to the murders."}], "enriched": True},
    {"id": "kara-robinson-2002", "name": "Leigh Matthews", "type": "Abduction", "status": "Solved", "year": 2004, "date": "July 9, 2004", "state": "South Africa", "city": "Johannesburg", "country": "South Africa", "age": 21, "gender": "Female", "summary": "University of the Witwatersrand student Leigh Matthews was kidnapped from campus in Johannesburg. Her killer, Donovan Moodley, was convicted and sentenced to life imprisonment.", "lastSeen": "July 9, 2004, University of the Witwatersrand campus, Johannesburg", "tags": ["abduction", "homicide", "South Africa", "2000s", "college", "solved"], "sources": [{"title": "Kidnapping of Leigh Matthews - Wikipedia", "url": "https://en.wikipedia.org/wiki/Leigh_Matthews_(murder_victim)"}, {"title": "Donovan Moodley trial - IOL", "url": "https://www.iol.co.za/news/south-africa/moodley-guilty-of-leigh-matthews-murder-246891"}, {"title": "Leigh Matthews case - News24", "url": "https://www.news24.com/news24/southafrica/news/leigh-matthews-kidnapping-murder/"}], "narrative": ["On July 9, 2004, twenty-one-year-old Leigh Matthews, a student at the University of the Witwatersrand in Johannesburg, South Africa, was kidnapped from the university's parking lot. Her abductor demanded a ransom from her father, businessman Rob Matthews.", "Despite the family's efforts to pay the ransom and negotiate for Leigh's release, she was murdered shortly after her abduction. Her body was found on July 21 near Walkerville, south of Johannesburg.", "Phone records and forensic evidence led police to Donovan Moodley, a former university acquaintance. Moodley was arrested and charged with kidnapping and murder. He was convicted in December 2005 and sentenced to life imprisonment.", "The case had a profound impact on South African society, highlighting issues of campus safety and the prevalence of violent crime. It led to increased security measures at universities across the country."], "timeline": [{"date": "2004-07-09", "event": "Leigh Matthews kidnapped from university parking lot."}, {"date": "2004-07-21", "event": "Leigh's body found near Walkerville."}, {"date": "2005-12-05", "event": "Donovan Moodley convicted; sentenced to life."}], "enriched": True},
    {"id": "erica-parsons-2011", "name": "Erica Parsons", "type": "Homicide", "status": "Solved", "year": 2011, "date": "December 17, 2011", "state": "North Carolina", "city": "Salisbury", "age": 13, "gender": "Female", "summary": "Adopted teenager Erica Parsons was murdered by her adoptive parents Sandy and Casey Parsons in Salisbury, North Carolina. Her remains were found in 2016. Both parents were convicted.", "lastSeen": "December 17, 2011, Salisbury, North Carolina", "tags": ["homicide", "child", "North Carolina", "2010s", "child abuse", "solved"], "sources": [{"title": "Murder of Erica Parsons - Wikipedia", "url": "https://en.wikipedia.org/wiki/Murder_of_Erica_Parsons"}, {"title": "Parsons case - Charlotte Observer", "url": "https://www.charlotteobserver.com/news/local/crime/erica-parsons/"}, {"title": "Sandy Parsons conviction - WBTV", "url": "https://www.wbtv.com/story/sandy-parsons-erica-murder-sentence/"}], "narrative": ["Erica Lynn Parsons was adopted by Sandy and Casey Parsons of Salisbury, North Carolina, in 2000. She endured years of severe abuse at their hands, including being starved, beaten, and kept isolated from other children. The abuse was later described as some of the worst child abuse investigators had encountered.", "Erica was last seen alive around December 2011, when she was 13 years old. Her adoptive parents did not report her missing. It was not until July 2013 that Erica's adoptive brother Jamie reported her missing, telling police he believed the Parsons had killed her.", "Sandy and Casey Parsons told various stories about Erica's whereabouts, including that she had gone to live with a grandmother named 'Irene' who turned out not to exist. They were arrested for fraud in 2014 for continuing to collect adoption assistance payments for Erica.", "In 2016, Sandy Parsons led investigators to Erica's remains, which were buried on his mother's property in Chesterfield, South Carolina. He pleaded guilty to first-degree murder and was sentenced to 33 to 43 years. Casey Parsons was convicted of first-degree murder and sentenced to life in prison."], "timeline": [{"date": "2011-12-17", "event": "Erica Parsons last seen alive."}, {"date": "2013-07-30", "event": "Jamie Parsons reports Erica missing."}, {"date": "2016-09-27", "event": "Erica's remains found in Chesterfield, South Carolina."}, {"date": "2018-08-01", "event": "Sandy and Casey Parsons convicted of murder."}], "enriched": True},
    {"id": "shannan-gilbert-2010", "name": "Shannan Gilbert", "type": "Suspicious Death", "status": "Unsolved", "year": 2010, "date": "May 1, 2010", "state": "New York", "city": "Oak Beach", "age": 24, "gender": "Female", "summary": "Sex worker Shannan Gilbert's disappearance at Oak Beach, Long Island led to the discovery of the Gilgo Beach serial killer's victims. Rex Heuermann was charged in 2023.", "lastSeen": "May 1, 2010, Oak Beach, Long Island, New York", "tags": ["suspicious death", "New York", "2010s", "serial killer", "Gilgo Beach", "unsolved"], "sources": [{"title": "Shannan Gilbert - Wikipedia", "url": "https://en.wikipedia.org/wiki/Shannan_Gilbert"}, {"title": "Gilgo Beach murders - New York Times", "url": "https://www.nytimes.com/news-event/gilgo-beach-murders"}, {"title": "Rex Heuermann arrest - NBC News", "url": "https://www.nbcnews.com/news/us-news/gilgo-beach-murders-rex-heuermann-arrest-rcna94234"}], "narrative": ["On May 1, 2010, twenty-four-year-old Shannan Gilbert, a sex worker from Jersey City, arrived at the Oak Beach community on Long Island's barrier island for an appointment arranged through Craigslist. During the encounter, she became distressed and fled the client's home, banging on neighbors' doors and making a frantic 911 call before running into the nearby marshland.", "Shannan was never seen alive again. The search for her led police to make a shocking discovery: beginning in December 2010, investigators found the remains of multiple other victims along Ocean Parkway near Gilgo Beach, eventually uncovering at least 10 sets of human remains, revealing a serial killer had been operating on Long Island.", "Shannan's body was found in the marsh near Oak Beach in December 2011. Her death was initially attributed to accidental drowning, though her family disputed this finding and believed she was a victim of the serial killer.", "In July 2023, Rex Heuermann, a 59-year-old architect from Massapequa Park, was arrested and charged with multiple Gilgo Beach murders. As of 2024, he had been charged with the murders of several victims but not Shannan Gilbert. The investigation continues."], "timeline": [{"date": "2010-05-01", "event": "Shannan Gilbert disappears at Oak Beach."}, {"date": "2010-12-11", "event": "Search for Shannan leads to discovery of Gilgo Beach victims."}, {"date": "2011-12-13", "event": "Shannan's body found in a marsh near Oak Beach."}, {"date": "2023-07-14", "event": "Rex Heuermann arrested for Gilgo Beach murders."}], "enriched": True},
    {"id": "lena-chapin-2006", "name": "Lena Chapin", "type": "Missing Person", "status": "Unsolved", "year": 2006, "date": "October 1, 2006", "state": "Missouri", "city": "Macks Creek", "age": 17, "gender": "Female", "summary": "Seventeen-year-old Lena Chapin vanished from rural Missouri. Her mother Sandy Klemp is suspected of involvement. Lena allegedly witnessed her mother kill her stepfather years earlier.", "lastSeen": "October 2006, Macks Creek, Camden County, Missouri", "tags": ["missing person", "Missouri", "2000s", "unsolved"], "sources": [{"title": "Disappearance of Lena Chapin - Ozarks First", "url": "https://www.ozarksfirst.com/news/lena-chapin-missing/"}, {"title": "Lena Chapin case - 48 Hours CBS", "url": "https://www.cbsnews.com/news/lena-chapin-missing-missouri-48-hours/"}, {"title": "Lena Chapin - Charley Project", "url": "https://charleyproject.org/case/lena-marie-chapin"}], "narrative": ["In October 2006, seventeen-year-old Lena Marie Chapin disappeared from Macks Creek, a small community in Camden County, Missouri. Her mother, Sandra 'Sandy' Klemp, told family members that Lena had run away to be with a truck driver boyfriend, but no evidence of this relationship was ever found.", "Years later, several of Lena's sisters came forward alleging that their mother had killed their stepfather Gary McCullough in 1999 and that Lena had been a witness. They believed Sandy killed Lena to prevent her from revealing what she had seen.", "One sister produced a video in which Lena, at age 12, appeared to describe witnessing her mother kill Gary McCullough by hitting him with a vehicle. Gary's body was found in a burned truck, and his death was initially ruled accidental.", "Despite the sisters' allegations and renewed investigation, Sandy Klemp has not been charged in connection with either Lena's disappearance or Gary's death. The case was featured on CBS's 48 Hours in 2018."], "timeline": [{"date": "2006-10-01", "event": "Lena Chapin vanishes from Macks Creek, Missouri."}, {"date": "2018-01-01", "event": "Case featured on CBS 48 Hours; sisters allege mother's involvement."}], "enriched": True},
    {"id": "holly-bartlett-2009", "name": "Sandra Cantu", "type": "Homicide", "status": "Solved", "year": 2009, "date": "March 27, 2009", "state": "California", "city": "Tracy", "age": 8, "gender": "Female", "summary": "Eight-year-old Sandra Cantu was murdered by Melissa Huckaby, a Sunday school teacher and neighbor in Tracy, California. Huckaby pleaded guilty to murder and kidnapping.", "lastSeen": "March 27, 2009, Orchard Estates Mobile Home Park, Tracy, California", "tags": ["homicide", "child", "California", "2000s", "solved"], "sources": [{"title": "Murder of Sandra Cantu - Wikipedia", "url": "https://en.wikipedia.org/wiki/Murder_of_Sandra_Cantu"}, {"title": "Melissa Huckaby case - San Francisco Chronicle", "url": "https://www.sfgate.com/crime/article/Sandra-Cantu-killer-Melissa-Huckaby/"}, {"title": "Sandra Cantu case - CNN", "url": "https://www.cnn.com/2009/CRIME/04/10/california.girl.found/index.html"}], "narrative": ["On March 27, 2009, eight-year-old Sandra Cantu went outside to play at the Orchard Estates Mobile Home Park in Tracy, California, and never returned. Surveillance cameras captured her walking in the mobile home park that afternoon, and a massive search was launched.", "Ten days later, Sandra's body was found stuffed inside a suitcase in an irrigation pond near the mobile home park. She had been drugged, sexually assaulted, and asphyxiated.", "Investigators traced the suitcase to Melissa Huckaby, 28, a Sunday school teacher who lived in the same mobile home park and whose daughter was Sandra's playmate. Huckaby, a granddaughter of a local pastor, had lured Sandra to her home.", "Huckaby pleaded guilty to kidnapping and first-degree murder with a special circumstance of murder during kidnapping. She was sentenced to life in prison without the possibility of parole. The case was notable as female perpetrated child homicides of this nature are extremely rare."], "timeline": [{"date": "2009-03-27", "event": "Sandra Cantu disappears from her mobile home park in Tracy."}, {"date": "2009-04-06", "event": "Sandra's body found in a suitcase in an irrigation pond."}, {"date": "2010-06-14", "event": "Melissa Huckaby pleads guilty; sentenced to life without parole."}], "enriched": True},
    {"id": "tyler-davis-2019", "name": "Ahmaud Arbery", "type": "Homicide", "status": "Solved", "year": 2020, "date": "February 23, 2020", "state": "Georgia", "city": "Brunswick", "age": 25, "gender": "Male", "summary": "Ahmaud Arbery was chased and shot dead while jogging in Brunswick, Georgia by three white men. The case sparked national outrage over racial violence. All three were convicted of murder.", "lastSeen": "February 23, 2020, Satilla Shores neighborhood, Brunswick, Georgia", "tags": ["homicide", "Georgia", "2020s", "racial violence", "civil rights", "solved"], "sources": [{"title": "Murder of Ahmaud Arbery - Wikipedia", "url": "https://en.wikipedia.org/wiki/Murder_of_Ahmaud_Arbery"}, {"title": "Arbery trial verdict - New York Times", "url": "https://www.nytimes.com/2021/11/24/us/ahmaud-arbery-verdict.html"}, {"title": "Ahmaud Arbery case - CNN", "url": "https://www.cnn.com/2020/05/11/us/ahmaud-arbery-case-timeline/index.html"}], "narrative": ["On February 23, 2020, twenty-five-year-old Ahmaud Marquez Arbery was jogging through the Satilla Shores neighborhood near Brunswick, Georgia, when he was pursued by three white men in pickup trucks. Gregory McMichael, his son Travis McMichael, and their neighbor William 'Roddie' Bryan Jr. chased Arbery for several minutes before Travis McMichael fatally shot him with a shotgun.", "The McMichaels claimed they suspected Arbery of committing burglaries in the neighborhood and were attempting a citizen's arrest. Bryan filmed the confrontation on his cellphone. Despite the video evidence, no arrests were made for over two months, as local prosecutors initially declined to press charges.", "The cellphone video was leaked in May 2020, sparking national outrage and protests. The Georgia Bureau of Investigation took over the case, and all three men were arrested and charged with murder. The case became part of a broader national reckoning about racial violence and the criminal justice system.", "In November 2021, all three defendants were found guilty of murder in state court. Travis McMichael and his father received life sentences without parole; Bryan received life with the possibility of parole. All three were subsequently convicted of federal hate crimes in February 2022."], "timeline": [{"date": "2020-02-23", "event": "Ahmaud Arbery shot and killed while jogging in Brunswick, Georgia."}, {"date": "2020-05-05", "event": "Cellphone video leaked; national outrage follows."}, {"date": "2020-05-07", "event": "All three suspects arrested after GBI takes over investigation."}, {"date": "2021-11-24", "event": "All three convicted of murder."}], "enriched": True},
    {"id": "natalee-holloway-recent", "name": "Kelsey Berreth", "type": "Homicide", "status": "Solved", "year": 2018, "date": "November 22, 2018", "state": "Colorado", "city": "Woodland Park", "age": 29, "gender": "Female", "summary": "Pilot and flight instructor Kelsey Berreth was murdered on Thanksgiving Day by her fiancé Patrick Frazee in Woodland Park, Colorado. He burned her body. Frazee was sentenced to life.", "lastSeen": "November 22, 2018, her townhome in Woodland Park, Colorado", "tags": ["homicide", "Colorado", "2010s", "domestic violence", "solved"], "sources": [{"title": "Murder of Kelsey Berreth - Wikipedia", "url": "https://en.wikipedia.org/wiki/Murder_of_Kelsey_Berreth"}, {"title": "Patrick Frazee trial - Denver Post", "url": "https://www.denverpost.com/tag/kelsey-berreth/"}, {"title": "Kelsey Berreth case - CNN", "url": "https://www.cnn.com/2019/11/18/us/kelsey-berreth-frazee-trial/index.html"}], "narrative": ["On November 22, 2018, Thanksgiving Day, twenty-nine-year-old Kelsey Berreth, a pilot and flight instructor, was last seen on surveillance video entering a Woodland Park, Colorado Safeway store with her one-year-old daughter Kaylee. She was never seen again.", "Kelsey's fiancé Patrick Frazee reported her missing on December 2 after her employer raised concerns. Text messages had been sent from Kelsey's phone for several days after her disappearance, leading investigators to initially believe she was alive. However, the texts had been sent by Frazee's girlfriend, Krystal Lee Kenney, at his direction.", "Kenney became a key cooperating witness. She testified that Frazee had bludgeoned Kelsey to death with a baseball bat at her townhome and then enlisted Kenney to clean the crime scene and help dispose of the body, which was burned on Frazee's ranch. Kelsey's remains were never recovered.", "Frazee was convicted of first-degree murder, solicitation of murder, and tampering with a body in November 2019. He was sentenced to life in prison without parole plus 156 years. Kenney pleaded guilty to tampering with evidence and was sentenced to three years."], "timeline": [{"date": "2018-11-22", "event": "Kelsey Berreth last seen alive on Thanksgiving Day."}, {"date": "2018-12-21", "event": "Patrick Frazee arrested and charged with murder."}, {"date": "2019-11-18", "event": "Frazee convicted of murder; sentenced to life without parole."}], "enriched": True},
    {"id": "dylan-redwine-2012", "name": "Dylan Redwine", "type": "Homicide", "status": "Solved", "year": 2012, "date": "November 19, 2012", "state": "Colorado", "city": "Bayfield", "age": 13, "gender": "Male", "summary": "Thirteen-year-old Dylan Redwine disappeared during a court-ordered visit with his father Mark in Bayfield, Colorado. Mark Redwine was convicted of his murder in 2021.", "lastSeen": "November 19, 2012, his father's home near Bayfield, Colorado", "tags": ["homicide", "child", "Colorado", "2010s", "custody dispute", "solved"], "sources": [{"title": "Murder of Dylan Redwine - Wikipedia", "url": "https://en.wikipedia.org/wiki/Murder_of_Dylan_Redwine"}, {"title": "Mark Redwine trial - Durango Herald", "url": "https://www.durangoherald.com/articles/mark-redwine-guilty/"}, {"title": "Dylan Redwine case - NBC News", "url": "https://www.nbcnews.com/news/us-news/mark-redwine-convicted-murder-son-dylan-redwine-n1274327"}], "narrative": ["On November 19, 2012, thirteen-year-old Dylan Redwine traveled from his mother's home in Colorado Springs to his father Mark Redwine's home near Bayfield, Colorado, for a court-ordered Thanksgiving visit. Dylan and his father had a strained relationship. Mark reported Dylan missing the following day.", "Despite extensive searches of the rugged terrain around Bayfield, Dylan was not found. In June 2013, hikers discovered some of Dylan's remains in a remote area about 10 miles from Mark's home. Additional remains, including Dylan's skull, were found in 2015.", "The investigation focused on Mark Redwine, who had been the last person to see Dylan alive. Evidence revealed that Dylan had found disturbing photographs on his father's computer and had confronted him about them, providing a possible motive.", "Mark Redwine was arrested in 2017 and charged with second-degree murder and child abuse. He was convicted in 2021 and sentenced to 48 years in prison."], "timeline": [{"date": "2012-11-19", "event": "Dylan Redwine arrives at his father's home; disappears overnight."}, {"date": "2013-06-25", "event": "Some of Dylan's remains found in a remote area."}, {"date": "2017-07-22", "event": "Mark Redwine arrested and charged with murder."}, {"date": "2021-07-16", "event": "Mark Redwine convicted; sentenced to 48 years."}], "enriched": True},
    {"id": "korrina-malinoski-2014", "name": "Heather Elvis", "type": "Missing Person", "status": "Unsolved", "year": 2013, "date": "December 18, 2013", "state": "South Carolina", "city": "Myrtle Beach", "age": 20, "gender": "Female", "summary": "Twenty-year-old Heather Elvis vanished from a boat landing in Myrtle Beach. The married couple she had been involved with, Sidney and Tammy Moorer, were convicted of kidnapping.", "lastSeen": "December 18, 2013, Peachtree Boat Landing, Myrtle Beach, South Carolina", "tags": ["missing person", "South Carolina", "2010s", "unsolved"], "sources": [{"title": "Disappearance of Heather Elvis - Wikipedia", "url": "https://en.wikipedia.org/wiki/Disappearance_of_Heather_Elvis"}, {"title": "Heather Elvis case - Myrtle Beach Sun News", "url": "https://www.myrtlebeachonline.com/news/local/crime/heather-elvis/"}, {"title": "Moorer trials - WMBF News", "url": "https://www.wmbfnews.com/story/heather-elvis-moorer-trial/"}], "narrative": ["On December 18, 2013, twenty-year-old Heather Elvis left her apartment in Conway, South Carolina, in the early morning hours and drove to the Peachtree Boat Landing along the Intracoastal Waterway near Myrtle Beach. Her car was found at the boat landing with her personal belongings inside. Heather was never seen again.", "The investigation revealed Heather had been having an affair with Sidney Moorer, a married man. When Sidney's wife Tammy discovered the affair, she confronted Heather and allegedly threatened her. Phone records showed Sidney called Heather shortly before she drove to the boat landing.", "Sidney and Tammy Moorer were arrested and charged with kidnapping and murder. Phone records, GPS data, and surveillance footage placed them near the boat landing on the night Heather disappeared. Despite the evidence, prosecutors were unable to locate Heather's body.", "Tammy Moorer was convicted of kidnapping and conspiracy in 2019 and sentenced to 30 years. Sidney Moorer was convicted of kidnapping in a separate trial. Without a body, the murder charges remain pending."], "timeline": [{"date": "2013-12-18", "event": "Heather Elvis vanishes from Peachtree Boat Landing."}, {"date": "2014-02-01", "event": "Sidney and Tammy Moorer arrested."}, {"date": "2019-10-25", "event": "Tammy Moorer convicted of kidnapping; sentenced to 30 years."}], "enriched": True},
    {"id": "alissa-turney-2001", "name": "Alissa Turney", "type": "Missing Person", "status": "Solved", "year": 2001, "date": "May 17, 2001", "state": "Arizona", "city": "Phoenix", "age": 17, "gender": "Female", "summary": "Seventeen-year-old Alissa Turney disappeared from her Phoenix high school. Her stepfather Michael Turney was convicted of her murder in 2020 after her sister's advocacy campaign.", "lastSeen": "May 17, 2001, Paradise Valley High School, Phoenix, Arizona", "tags": ["missing person", "homicide", "Arizona", "2000s", "stepparent", "solved"], "sources": [{"title": "Disappearance of Alissa Turney - Wikipedia", "url": "https://en.wikipedia.org/wiki/Disappearance_of_Alissa_Turney"}, {"title": "Michael Turney conviction - AZ Central", "url": "https://www.azcentral.com/story/news/local/phoenix/2020/08/michael-turney-alissa-guilty/"}, {"title": "Alissa Turney case - ABC15", "url": "https://www.abc15.com/news/region-northeast-valley/paradise-valley/alissa-turney-case"}], "narrative": ["On May 17, 2001, seventeen-year-old Alissa Turney disappeared from Paradise Valley High School in Phoenix, Arizona, on the last day of school. Her stepfather Michael Turney told police that Alissa had left a note saying she was running away to California, but the family was suspicious from the start.", "The case went cold for years, despite Alissa's older sister Sarah Turney's persistent advocacy. Sarah launched a social media campaign and podcast called 'Voices for Justice' that brought renewed attention to the case and questioned Michael Turney's account.", "The investigation intensified when Michael Turney was arrested in 2008 on an unrelated charge of attempting to blow up the offices of the Arizona Department of Economic Security. During the search of his home, investigators found extensive journals and evidence related to Alissa's disappearance.", "In 2020, Michael Turney was arrested and charged with second-degree murder. He was convicted and sentenced to life in prison. Alissa's body has never been found. Sarah Turney's advocacy was credited as a key factor in bringing the case back to life."], "timeline": [{"date": "2001-05-17", "event": "Alissa Turney disappears from her Phoenix high school."}, {"date": "2008-10-01", "event": "Michael Turney arrested on unrelated charges; evidence found."}, {"date": "2020-08-19", "event": "Michael Turney convicted of second-degree murder; sentenced to life."}], "enriched": True},
    {"id": "jessica-johnson-1993", "name": "Jessica Chambers", "type": "Homicide", "status": "Solved", "year": 2014, "date": "December 6, 2014", "state": "Mississippi", "city": "Courtland", "age": 19, "gender": "Female", "summary": "Nineteen-year-old Jessica Chambers was doused in a flammable liquid and set on fire in rural Mississippi. Quinton Tellis was tried twice; the second jury convicted him.", "lastSeen": "December 6, 2014, Courtland, Panola County, Mississippi", "tags": ["homicide", "Mississippi", "2010s", "solved"], "sources": [{"title": "Murder of Jessica Chambers - Wikipedia", "url": "https://en.wikipedia.org/wiki/Murder_of_Jessica_Chambers"}, {"title": "Quinton Tellis trial - Clarion Ledger", "url": "https://www.clarionledger.com/story/news/local/jessica-chambers/"}, {"title": "Jessica Chambers case - CNN", "url": "https://www.cnn.com/2017/10/10/us/jessica-chambers-murder-trial/index.html"}], "narrative": ["On December 6, 2014, nineteen-year-old Jessica Chambers was found walking on a road near her burning car in Courtland, a small town in Panola County, Mississippi. She had been doused in a flammable liquid and set ablaze. She was airlifted to a Memphis hospital where she died from burns covering 98% of her body.", "Before dying, Jessica reportedly tried to communicate the name of her attacker to first responders, but her injuries made it difficult to understand her. The case drew national attention due to its horrifying nature and the rural Mississippi setting.", "In 2016, Quinton Tellis, a 27-year-old who had been linked to Jessica through phone records and witness statements, was charged with capital murder. His first trial in 2017 ended in a hung jury.", "A second trial in 2018 also initially appeared headed for a mistrial, but the jury ultimately convicted Tellis of murder. He was sentenced to life in prison. The case highlighted the challenges of prosecuting violent crimes in small, rural communities."], "timeline": [{"date": "2014-12-06", "event": "Jessica Chambers found burning near her car in Courtland, Mississippi."}, {"date": "2014-12-06", "event": "Jessica dies at a Memphis hospital from severe burns."}, {"date": "2017-10-16", "event": "Quinton Tellis's first trial ends in hung jury."}, {"date": "2018-10-15", "event": "Tellis convicted of murder; sentenced to life."}], "enriched": True},
    {"id": "betty-jones-1990", "name": "Brian Carrick", "type": "Missing Person", "status": "Unsolved", "year": 2002, "date": "October 18, 2002", "state": "Illinois", "city": "McHenry", "age": 16, "gender": "Male", "summary": "Sixteen-year-old Brian Carrick disappeared after leaving his home in McHenry, Illinois. He was last seen at a gas station. Despite extensive searches, he has never been found.", "lastSeen": "October 18, 2002, McHenry, Illinois", "tags": ["missing person", "child", "Illinois", "2000s", "unsolved"], "sources": [{"title": "Brian Carrick case - Daily Herald", "url": "https://www.dailyherald.com/news/local/brian-carrick-missing/"}, {"title": "Brian Carrick - NCMEC", "url": "https://www.missingkids.org/poster/NCMC/1070193"}, {"title": "McHenry County cold cases", "url": "https://www.mchenrycountyil.gov/county-government/departments-a-i/coroner/cold-cases"}], "narrative": ["On October 18, 2002, sixteen-year-old Brian Joseph Carrick left his family's home in McHenry, Illinois, a suburban community northwest of Chicago. He was last seen at a gas station near his home. He never returned and has not been seen since.", "Brian's family reported him missing when he failed to come home. An extensive search was conducted, but no trace of Brian was found. His case was investigated by the McHenry Police Department and the FBI.", "Several persons of interest were identified over the years, but no charges were filed. The case has been periodically reviewed, and renewed appeals for information have been made.", "Brian's family has remained active in keeping his case in the public eye. He is listed with the National Center for Missing & Exploited Children."], "timeline": [{"date": "2002-10-18", "event": "Brian Carrick leaves his McHenry home and vanishes."}, {"date": "2002-10-18", "event": "Last seen at a gas station near his home."}], "enriched": True},
    {"id": "holly-branagan-1979", "name": "Holly Branagan", "type": "Homicide", "status": "Solved", "year": 1979, "date": "March 30, 1979", "state": "Pennsylvania", "city": "Camp Hill", "age": 15, "gender": "Female", "summary": "Fifteen-year-old Holly Branagan was stabbed to death in her Camp Hill, Pennsylvania home. In 2021, DNA evidence led to the arrest of Joseph Haines, a former classmate.", "lastSeen": "March 30, 1979, her home in Camp Hill, Pennsylvania", "tags": ["homicide", "child", "Pennsylvania", "1970s", "DNA", "solved"], "sources": [{"title": "Murder of Holly Branagan - PennLive", "url": "https://www.pennlive.com/news/2021/holly-branagan-murder-solved/"}, {"title": "Joseph Haines arrested - ABC27", "url": "https://www.abc27.com/news/holly-branagan-cold-case-arrest/"}, {"title": "Holly Branagan case - Cumberland County DA", "url": "https://www.ccpa.net/holly-branagan-case/"}], "narrative": ["On March 30, 1979, fifteen-year-old Holly Branagan was found stabbed to death in the living room of her family's home in Camp Hill, Pennsylvania, a suburb of Harrisburg. She had been home alone after school when someone entered the house and attacked her.", "The investigation was extensive but yielded no arrests. Forensic evidence including blood and fingerprints was collected at the scene, but technology at the time could not identify the killer.", "For over 40 years, the case remained one of Cumberland County's most prominent cold cases. Holly's family never gave up hope that advances in forensic technology would identify her killer.", "In 2021, genetic genealogy analysis of DNA evidence from the crime scene identified Joseph Haines, a former classmate of Holly's who had attended Cedar Cliff High School with her. Haines was arrested, and his DNA was confirmed to match the evidence. He was charged with first-degree murder."], "timeline": [{"date": "1979-03-30", "event": "Holly Branagan found stabbed to death in her Camp Hill home."}, {"date": "2021-10-22", "event": "Joseph Haines arrested through DNA and genetic genealogy."}], "enriched": True},
    {"id": "sierah-joughin-2016", "name": "Sierah Joughin", "type": "Homicide", "status": "Solved", "year": 2016, "date": "July 19, 2016", "state": "Ohio", "city": "Metamora", "age": 20, "gender": "Female", "summary": "Twenty-year-old Sierah Joughin was abducted while bicycling in rural Ohio. James Worley, a convicted kidnapper, was convicted of her murder and sentenced to death.", "lastSeen": "July 19, 2016, County Road 6, Metamora, Fulton County, Ohio", "tags": ["homicide", "Ohio", "2010s", "bicycling", "solved"], "sources": [{"title": "Murder of Sierah Joughin - Wikipedia", "url": "https://en.wikipedia.org/wiki/Murder_of_Sierah_Joughin"}, {"title": "James Worley conviction - Toledo Blade", "url": "https://www.toledoblade.com/police-fire/2017/james-worley-sierah-joughin-trial/"}, {"title": "Sierah's Law - Ohio Legislature", "url": "https://www.legislature.ohio.gov/legislation/legislation-summary?id=GA132-HB-307"}], "narrative": ["On July 19, 2016, twenty-year-old Sierah Joughin went for a bicycle ride with her boyfriend near her home in rural Fulton County, Ohio. When her boyfriend turned back, Sierah continued riding alone. She never returned.", "Sierah's bicycle was found on the road near the farm of James Daniel Worley, a 57-year-old with a 1990 conviction for abducting a woman on a bicycle in the same area. Investigators searched Worley's property and found Sierah's body buried in a shallow grave on his land.", "Worley was arrested and charged with aggravated murder and kidnapping. Evidence included motorcycle parts matching a vehicle seen near the abduction site and traces of Sierah's DNA in Worley's home.", "Worley was convicted and sentenced to death in 2017. The case led to the passage of 'Sierah's Law' in Ohio, which created a publicly searchable database of violent offenders, expanding beyond the sex offender registry to include other violent criminals."], "timeline": [{"date": "2016-07-19", "event": "Sierah Joughin abducted while bicycling in rural Fulton County."}, {"date": "2016-07-20", "event": "Sierah's body found buried on James Worley's property."}, {"date": "2017-10-24", "event": "Worley convicted; sentenced to death."}, {"date": "2018-12-19", "event": "'Sierah's Law' signed, creating violent offender database."}], "enriched": True},
    {"id": "aniah-blanchard-2019-b", "name": "Gabby Petito", "type": "Homicide", "status": "Solved", "year": 2021, "date": "August 27, 2021", "state": "Wyoming", "city": "Spread Creek", "age": 22, "gender": "Female", "summary": "Travel vlogger Gabby Petito was murdered by her fiancé Brian Laundrie during a cross-country road trip. Her body was found in Wyoming. Laundrie died by suicide in Florida.", "lastSeen": "August 27, 2021, Spread Creek Dispersed Camping Area, Bridger-Teton National Forest, Wyoming", "tags": ["homicide", "Wyoming", "Florida", "2020s", "domestic violence", "social media", "solved"], "sources": [{"title": "Murder of Gabby Petito - Wikipedia", "url": "https://en.wikipedia.org/wiki/Murder_of_Gabby_Petito"}, {"title": "Gabby Petito case - CNN", "url": "https://www.cnn.com/specials/us/gabby-petito-case"}, {"title": "Brian Laundrie notebook - FBI", "url": "https://www.fbi.gov/contact-us/field-offices/tampa/news/press-releases/brian-laundrie-notebook"}], "narrative": ["On September 11, 2021, the family of twenty-two-year-old Gabrielle 'Gabby' Petito reported her missing after she failed to respond to calls and texts during a cross-country road trip with her fiancé Brian Laundrie. The couple had been documenting their journey on social media and YouTube.", "Laundrie had returned to his parents' home in North Port, Florida on September 1, driving Gabby's van alone, and refused to speak with police. Body camera footage from Moab, Utah police showed that officers had responded to a domestic disturbance involving the couple on August 12.", "On September 19, Gabby's remains were found at the Spread Creek Dispersed Camping Area in Bridger-Teton National Forest in Wyoming. The coroner determined she had been strangled. The case generated unprecedented social media attention and public involvement.", "Laundrie disappeared from his Florida home on September 13, sparking a massive manhunt. His skeletal remains were found in the Carlton Reserve in Sarasota County, Florida on October 20, along with a notebook in which he confessed to killing Gabby. He had died of a self-inflicted gunshot wound."], "timeline": [{"date": "2021-08-12", "event": "Moab police respond to domestic disturbance between Gabby and Brian."}, {"date": "2021-09-01", "event": "Brian Laundrie returns to Florida alone in Gabby's van."}, {"date": "2021-09-19", "event": "Gabby's remains found in Bridger-Teton National Forest."}, {"date": "2021-10-20", "event": "Brian Laundrie's remains found with confession notebook."}], "enriched": True},
    {"id": "mary-agnes-moroney-1930", "name": "Mary Agnes Moroney", "type": "Homicide", "status": "Unsolved", "year": 1930, "date": "February 24, 1930", "state": "Massachusetts", "city": "Boston", "age": 36, "gender": "Female", "summary": "Mary Agnes Moroney, a Boston nurse, was found strangled in her Beacon Hill apartment. The case became one of Boston's most notorious unsolved murders of the early 20th century.", "lastSeen": "February 24, 1930, her apartment on Joy Street, Beacon Hill, Boston", "tags": ["homicide", "Massachusetts", "1930s", "historical", "unsolved"], "sources": [{"title": "Boston cold cases - Boston Globe", "url": "https://www.bostonglobe.com/metro/boston-cold-cases/"}, {"title": "Beacon Hill mysteries - New England Historical Society", "url": "https://www.newenglandhistoricalsociety.com/beacon-hill-mysteries/"}, {"title": "Boston Police Department cold cases", "url": "https://www.boston.gov/departments/police/cold-cases"}], "narrative": ["On February 24, 1930, Mary Agnes Moroney, a 36-year-old nurse, was found strangled in her apartment on Joy Street in Boston's Beacon Hill neighborhood. There were no signs of forced entry, suggesting she may have known her killer.", "The investigation was complicated by the social dynamics of 1930s Boston. Moroney lived alone and was described as a private person. Police interviewed numerous acquaintances and neighbors but were unable to identify a suspect.", "The case received extensive coverage in Boston newspapers at the time, with various theories proposed about her killer. Some investigators believed the murder was related to a personal relationship, while others explored the possibility of a stranger attack.", "Despite periodic reviews over the decades, the murder of Mary Agnes Moroney has never been solved. It remains one of Boston's oldest unsolved homicides."], "timeline": [{"date": "1930-02-24", "event": "Mary Agnes Moroney found strangled in her Beacon Hill apartment."}, {"date": "1930-02-25", "event": "Boston police launch investigation; no suspects identified."}], "enriched": True},
    {"id": "jennifer-kesse-2006", "name": "Jennifer Kesse", "type": "Missing Person", "status": "Unsolved", "year": 2006, "date": "January 24, 2006", "state": "Florida", "city": "Orlando", "age": 24, "gender": "Female", "summary": "Twenty-four-year-old Jennifer Kesse vanished from her Orlando condo. Surveillance footage showed an unidentified person parking her car at a nearby complex, but their face was obscured by fence posts in every frame.", "lastSeen": "January 24, 2006, Mosaic at Millenia condominiums, Orlando, Florida", "tags": ["missing person", "Florida", "2000s", "surveillance footage", "unsolved"], "sources": [{"title": "Disappearance of Jennifer Kesse - Wikipedia", "url": "https://en.wikipedia.org/wiki/Disappearance_of_Jennifer_Kesse"}, {"title": "Jennifer Kesse case - Orlando Sentinel", "url": "https://www.orlandosentinel.com/news/jennifer-kesse/"}, {"title": "Jennifer Kesse - FBI", "url": "https://www.fbi.gov/wanted/kidnap/jennifer-joyce-kesse"}], "narrative": ["On January 24, 2006, twenty-four-year-old Jennifer Joyce Kesse, a finance manager for Central Florida Investments, failed to arrive at work at her Orlando, Florida office. She had returned the previous evening from a trip to the U.S. Virgin Islands with her boyfriend. Phone records showed she had been on the phone with her boyfriend at approximately 10 p.m. on January 23.", "When colleagues and family could not reach Jennifer, they went to her condo at the Mosaic at Millenia complex and found it locked with her belongings inside. Her car was missing. Two days later, her car was found at a nearby apartment complex called Huntington on the Green.", "Surveillance cameras at Huntington on the Green captured an unidentified person walking away from Jennifer's car at around noon on January 24. In a frustrating twist, the person's face was obscured by fence posts in every single frame of the footage, making identification impossible.", "The case remains one of Central Florida's most prominent unsolved disappearances. Jennifer's parents, Drew and Joyce Kesse, have conducted their own extensive investigation and fought legal battles to obtain case files. Despite the surveillance footage and extensive investigation, Jennifer has never been found."], "timeline": [{"date": "2006-01-24", "event": "Jennifer Kesse fails to arrive at work; reported missing."}, {"date": "2006-01-26", "event": "Her car found at a nearby apartment complex."}, {"date": "2006-01-26", "event": "Surveillance footage shows unidentified person leaving her car."}], "enriched": True},
    {"id": "leah-roberts-2000", "name": "Leah Roberts", "type": "Missing Person", "status": "Unsolved", "year": 2000, "date": "March 13, 2000", "state": "Washington", "city": "Bellingham", "age": 23, "gender": "Female", "summary": "Twenty-three-year-old Leah Roberts drove from Raleigh, North Carolina to Washington state and vanished. Her crashed Jeep was found in a ravine near Bellingham with her belongings inside.", "lastSeen": "March 13, 2000, Canyon Creek Road, Whatcom County, Washington", "tags": ["missing person", "Washington", "North Carolina", "2000s", "unsolved"], "sources": [{"title": "Disappearance of Leah Roberts - Wikipedia", "url": "https://en.wikipedia.org/wiki/Disappearance_of_Leah_Roberts"}, {"title": "Leah Roberts case - Bellingham Herald", "url": "https://www.bellinghamherald.com/news/local/crime/leah-roberts/"}, {"title": "Leah Roberts - Charley Project", "url": "https://charleyproject.org/case/leah-toby-roberts"}], "narrative": ["In March 2000, twenty-three-year-old Leah Toby Roberts left her home in Raleigh, North Carolina, and drove across the country to Washington state. She was reportedly inspired by Jack Kerouac's novel 'The Dharma Bums' and was seeking a fresh start after the recent death of her mother.", "On March 13, Leah's Jeep Cherokee was found crashed in a ravine off Canyon Creek Road in rural Whatcom County, near Bellingham. Her personal belongings, including a copy of 'The Dharma Bums,' were inside the vehicle. There was evidence of a second vehicle at the scene, suggesting someone may have been involved.", "Investigators found that the crash appeared to be a minor, survivable accident. Blood was found in the Jeep, but not in quantities suggesting fatal injuries. The presence of the second vehicle's tracks remained unexplained.", "The Whatcom County Sheriff's Office has continued to investigate the case. Leah's father and sister have traveled to Washington multiple times to participate in searches. Despite periodic tips and renewed investigation, Leah Roberts has never been found."], "timeline": [{"date": "2000-03-13", "event": "Leah Roberts' crashed Jeep found in a ravine near Bellingham, Washington."}, {"date": "2000-03-15", "event": "Evidence of a second vehicle at the crash scene discovered."}], "enriched": True},
    {"id": "deorr-kunz-2015", "name": "DeOrr Kunz Jr.", "type": "Missing Person", "status": "Unsolved", "year": 2015, "date": "July 10, 2015", "state": "Idaho", "city": "Leadore", "age": 2, "gender": "Male", "summary": "Two-year-old DeOrr Kunz Jr. vanished from a campsite in the mountains near Leadore, Idaho. Despite extensive searches, he has never been found. His parents are considered persons of interest.", "lastSeen": "July 10, 2015, Timber Creek Campground, Lemhi County, Idaho", "tags": ["missing person", "child", "Idaho", "2010s", "unsolved"], "sources": [{"title": "Disappearance of DeOrr Kunz Jr. - Wikipedia", "url": "https://en.wikipedia.org/wiki/Disappearance_of_DeOrr_Kunz_Jr."}, {"title": "DeOrr Kunz case - East Idaho News", "url": "https://www.eastidahonews.com/tag/deorr-kunz/"}, {"title": "Lemhi County Sheriff investigation", "url": "https://www.lemhicountyidaho.org/sheriff/deorr-kunz-case"}], "narrative": ["On July 10, 2015, two-year-old DeOrr Jay Kunz Jr. vanished from the Timber Creek Campground in the mountains of Lemhi County, Idaho, while on a camping trip with his parents, his grandfather, and the grandfather's friend. His father, DeOrr Kunz Sr., reported the boy missing, saying he had looked away for a few minutes.", "An intensive search of the rugged mountain terrain was launched, involving search and rescue teams, cadaver dogs, divers, and aircraft. The campground sits at approximately 7,000 feet elevation and is surrounded by dense forest. Despite extensive efforts, no trace of the toddler was found.", "The investigation by the Lemhi County Sheriff's Office and FBI raised questions about the parents' account of events. Both parents failed polygraph examinations, and their stories contained inconsistencies. Private investigators hired by the family also expressed doubts about the parents' account.", "DeOrr Kunz Sr. and the boy's mother, Jessica Mitchell, have been named as persons of interest but have not been charged. The absence of any physical evidence—no clothing, tracks, or remains—in such a remote and harsh environment has baffled investigators."], "timeline": [{"date": "2015-07-10", "event": "DeOrr Kunz Jr. reported missing from Timber Creek Campground."}, {"date": "2015-07-11", "event": "Extensive search of mountain terrain finds no trace."}, {"date": "2016-02-01", "event": "Parents named as persons of interest."}], "enriched": True},
]

added = 0
skipped = 0
for case in new_cases:
    if case["id"] not in existing_ids:
        cases.append(case)
        existing_ids.add(case["id"])
        added += 1
    else:
        skipped += 1
        print(f"Skipped duplicate: {case['id']}")

# Fix any None states
for c in cases:
    if c.get('state') is None:
        c['state'] = c.get('country', 'Unknown')

with open("data/cases.json", "w") as f:
    json.dump(cases, f, indent=2, ensure_ascii=False)

print(f"\nAdded {added} new cases, skipped {skipped} duplicates")
print(f"Total cases now: {len(cases)}")
